import React, { useState } from 'react';
import { gql, useQuery } from '@apollo/client';

const SEARCH_QUERY = gql`
  query Search($query: String!, $limit: Int) {
    search(query: $query, limit: $limit) {
      artists {
        id
        name
        nb_fan
        nb_album
        picture_medium
      }
      albums {
        id
        title
        cover_medium
        release_date
        artist { name }
      }
      tracks {
        id
        title
        duration
        rank
        explicit_lyrics
        artist { name }
        album { title cover_medium }
      }
    }
  }
`;

const TOP_ARTISTS_QUERY = gql`
  query TopArtists($limit: Int) {
    topArtists(limit: $limit) {
      id
      name
      nb_fan
      nb_album
      picture_medium
    }
  }
`;

const TOP_TRACKS_QUERY = gql`
  query TopTracks($limit: Int) {
    topTracks(limit: $limit) {
      id
      title
      rank
      duration
      explicit_lyrics
      artist { name }
      album { cover_medium }
    }
  }
`;

function formatDuration(seconds) {
  if (!seconds && seconds !== 0) return '—';
  const m = Math.floor(seconds / 60);
  const s = String(seconds % 60).padStart(2, '0');
  return `${m}:${s}`;
}

export default function Search({ token }) {
  const [searchQuery, setSearchQuery] = useState('');
  const [hasSearched, setHasSearched] = useState(false);
  const [showTop, setShowTop] = useState(false);

  const authHeaders = { context: { headers: { authorization: `Bearer ${token}` } } };

  const { data, loading, error } = useQuery(SEARCH_QUERY, {
    variables: { query: searchQuery, limit: 20 },
    skip: !searchQuery || !hasSearched,
    ...authHeaders,
  });

  const { data: topArtistsData } = useQuery(TOP_ARTISTS_QUERY, {
    variables: { limit: 10 },
    skip: !showTop,
    ...authHeaders,
  });

  const { data: topTracksData } = useQuery(TOP_TRACKS_QUERY, {
    variables: { limit: 10 },
    skip: !showTop,
    ...authHeaders,
  });

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) setHasSearched(true);
  };

  const artists   = data?.search?.artists   || [];
  const albums    = data?.search?.albums    || [];
  const tracks    = data?.search?.tracks    || [];
  const topArtists = topArtistsData?.topArtists || [];
  const topTracks  = topTracksData?.topTracks   || [];

  return (
    <div>
      <h2>🔍 Recherche</h2>

      <div className="filter-section">
        <form onSubmit={handleSearch} style={{ display: 'flex', gap: '0.5rem' }}>
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => { setSearchQuery(e.target.value); setHasSearched(false); }}
            placeholder="Rechercher artistes, albums, pistes..."
            style={{
              flex: 1, padding: '0.75rem',
              border: '1px solid #ddd', borderRadius: '4px', fontSize: '0.95rem',
            }}
          />
          <button type="submit" className="btn-primary">🔍 Rechercher</button>
        </form>

        <button
          onClick={() => setShowTop(!showTop)}
          className="btn-secondary"
          style={{ marginTop: '1rem' }}
        >
          {showTop ? '❌ Masquer' : '🏆 Top 10'}
        </button>
      </div>

      {/* Top 10 */}
      {showTop && (
        <div className="items-grid" style={{ marginTop: '1rem' }}>
          {/* Top Artistes */}
          <div className="card">
            <h3>🏆 Top Artistes</h3>
            {topArtists.map((artist, idx) => (
              <div key={artist.id} style={{
                display: 'flex', alignItems: 'center', gap: '0.75rem',
                padding: '0.5rem 0', borderBottom: '1px solid #eee',
              }}>
                <span style={{ color: '#999', minWidth: 20, textAlign: 'right', fontSize: 13 }}>{idx + 1}</span>
                {artist.picture_medium
                  ? <img src={artist.picture_medium} alt="" style={{ width: 32, height: 32, borderRadius: '50%', objectFit: 'cover', flexShrink: 0 }} onError={e => e.target.style.display = 'none'} />
                  : <div style={{ width: 32, height: 32, borderRadius: '50%', background: '#eee', flexShrink: 0 }} />
                }
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontWeight: 500, fontSize: 14, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{artist.name}</div>
                  <div style={{ fontSize: 12, color: '#999' }}>
                    {artist.nb_fan?.toLocaleString('fr-FR') ?? 0} fans · {artist.nb_album ?? 0} albums
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Top Pistes */}
          <div className="card">
            <h3>🏆 Top Pistes</h3>
            {topTracks.map((track, idx) => (
              <div key={track.id} style={{
                display: 'flex', alignItems: 'center', gap: '0.75rem',
                padding: '0.5rem 0', borderBottom: '1px solid #eee',
              }}>
                <span style={{ color: '#999', minWidth: 20, textAlign: 'right', fontSize: 13 }}>{idx + 1}</span>
                {track.album?.cover_medium
                  ? <img src={track.album.cover_medium} alt="" style={{ width: 32, height: 32, borderRadius: 4, objectFit: 'cover', flexShrink: 0 }} onError={e => e.target.style.display = 'none'} />
                  : <div style={{ width: 32, height: 32, borderRadius: 4, background: '#eee', flexShrink: 0 }} />
                }
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontWeight: 500, fontSize: 14, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {track.explicit_lyrics && (
                      <span style={{ background: '#FCEBEB', color: '#A32D2D', fontSize: 9, padding: '1px 5px', borderRadius: 3, marginRight: 5 }}>E</span>
                    )}
                    {track.title}
                  </div>
                  <div style={{ fontSize: 12, color: '#999' }}>{track.artist?.name}</div>
                </div>
                <div style={{ fontSize: 12, color: '#999', flexShrink: 0 }}>
                  <div>★ {track.rank?.toLocaleString('fr-FR') ?? '—'}</div>
                  <div>{formatDuration(track.duration)}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Résultats de recherche */}
      {hasSearched && (
        <div style={{ marginTop: '1.5rem' }}>
          <h3 style={{ marginBottom: '1rem' }}>📊 Résultats</h3>

          {loading && <div className="loading">⏳ Recherche en cours...</div>}
          {error   && <div className="error">❌ Erreur : {error.message}</div>}

          {!loading && !error && artists.length === 0 && albums.length === 0 && tracks.length === 0 && (
            <div className="empty">😕 Aucun résultat pour « {searchQuery} »</div>
          )}

          {/* Artistes */}
          {artists.length > 0 && (
            <div className="card" style={{ marginBottom: '1.5rem' }}>
              <h4>🎤 Artistes ({artists.length})</h4>
              {artists.map((artist) => (
                <div key={artist.id} style={{
                  display: 'flex', alignItems: 'center', gap: '0.75rem',
                  padding: '0.75rem 0', borderBottom: '1px solid #eee',
                }}>
                  {artist.picture_medium
                    ? <img src={artist.picture_medium} alt="" style={{ width: 40, height: 40, borderRadius: '50%', objectFit: 'cover', flexShrink: 0 }} onError={e => e.target.style.display = 'none'} />
                    : <div style={{ width: 40, height: 40, borderRadius: '50%', background: '#eee', flexShrink: 0 }} />
                  }
                  <div>
                    <div style={{ fontWeight: 500 }}>{artist.name}</div>
                    <div style={{ fontSize: 12, color: '#999' }}>
                      {artist.nb_fan?.toLocaleString('fr-FR') ?? 0} fans · {artist.nb_album ?? 0} albums
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Albums */}
          {albums.length > 0 && (
            <div className="card" style={{ marginBottom: '1.5rem' }}>
              <h4>💿 Albums ({albums.length})</h4>
              {albums.map((album) => (
                <div key={album.id} style={{
                  display: 'flex', alignItems: 'center', gap: '0.75rem',
                  padding: '0.75rem 0', borderBottom: '1px solid #eee',
                }}>
                  {album.cover_medium
                    ? <img src={album.cover_medium} alt="" style={{ width: 40, height: 40, borderRadius: 4, objectFit: 'cover', flexShrink: 0 }} onError={e => e.target.style.display = 'none'} />
                    : <div style={{ width: 40, height: 40, borderRadius: 4, background: '#eee', flexShrink: 0 }} />
                  }
                  <div>
                    <div style={{ fontWeight: 500 }}>{album.title}</div>
                    <div style={{ fontSize: 12, color: '#999' }}>
                      {album.artist?.name}
                      {album.release_date && ` · ${new Date(album.release_date).getFullYear()}`}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Pistes */}
          {tracks.length > 0 && (
            <div className="card">
              <h4>🎵 Pistes ({tracks.length})</h4>
              {tracks.map((track) => (
                <div key={track.id} style={{
                  display: 'flex', alignItems: 'center', gap: '0.75rem',
                  padding: '0.75rem 0', borderBottom: '1px solid #eee',
                }}>
                  {track.album?.cover_medium
                    ? <img src={track.album.cover_medium} alt="" style={{ width: 40, height: 40, borderRadius: 4, objectFit: 'cover', flexShrink: 0 }} onError={e => e.target.style.display = 'none'} />
                    : <div style={{ width: 40, height: 40, borderRadius: 4, background: '#eee', flexShrink: 0 }} />
                  }
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 500, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      {track.explicit_lyrics && (
                        <span style={{ background: '#FCEBEB', color: '#A32D2D', fontSize: 9, padding: '1px 5px', borderRadius: 3, marginRight: 5 }}>E</span>
                      )}
                      {track.title}
                    </div>
                    <div style={{ fontSize: 12, color: '#999' }}>
                      {track.artist?.name} · {track.album?.title}
                    </div>
                  </div>
                  <div style={{ fontSize: 12, color: '#999', textAlign: 'right', flexShrink: 0 }}>
                    <div>{formatDuration(track.duration)}</div>
                    {track.rank && <div>★ {track.rank.toLocaleString('fr-FR')}</div>}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
